<section class="section page-top"><div class="container portal-layout"><?php require ROOT_PATH.'/app/Views/client/_nav.php'; ?><div><h1>Pembayaran</h1><form class="panel form-grid" method="post" enctype="multipart/form-data" action="<?= url('client/pembayaran') ?>"><?= csrf_field() ?><label>Project<select name="project_id" required><option value="">Pilih</option><?php foreach($projects as $p): ?><option value="<?= e($p['id']) ?>"><?= e($p['project_no'].' - '.$p['title']) ?></option><?php endforeach; ?></select></label><label>Jenis<select name="payment_type" required><option value="dp">DP</option><option value="termin">Termin</option><option value="pelunasan">Pelunasan</option></select></label><label>Jumlah<input type="number" min="1" name="amount" required></label><label>Bukti Transfer<input type="file" name="proof" accept="image/png,image/jpeg,application/pdf" required></label><div class="full"><button class="btn primary">Upload Bukti Pembayaran</button></div></form><div class="table-wrap"><table><tr><th>Project</th><th>Jenis</th><th>Jumlah</th><th>Status</th><th>Kwitansi</th></tr><?php foreach($rows as $r): ?><tr><td><?= e($r['project_title']) ?></td><td><?= e($r['payment_type']) ?></td><td><?= money($r['amount']) ?></td><td><?= e($r['status']) ?></td><td><?php if($r['receipt_no']): ?><span><?= e($r['receipt_no']) ?></span><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?></table></div></div></div></section>